<script setup>import {computed,ref} from 'vue';import {state} from '../../domain/prototypeStore.js';const type=ref('全部'),status=ref('全部');const rows=computed(()=>state.events.filter(e=>(type.value==='全部'||e.type===type.value)&&(status.value==='全部'||e.status===status.value)));const done=computed(()=>state.tasks.filter(t=>t.status==='已完成').length);</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">统</div><div><h2>数据统计</h2><p>事件、任务、演练与打卡概览</p></div></div><div class="metric-grid"><article><small>事件数量</small><strong>{{rows.length}}</strong></article><article><small>任务完成率</small><strong>{{state.tasks.length?Math.round(done/state.tasks.length*100):0}}%</strong></article><article><small>演练次数</small><strong>{{state.drills.length}}</strong></article><article><small>有效打卡</small><strong>{{state.checkins.filter(x=>x.status==='有效').length}}</strong></article></div><div class="button-row"><select v-model="type"><option>全部</option><option v-for="x in [...new Set(state.events.map(e=>e.type))]" :key="x">{{x}}</option></select><select v-model="status"><option>全部</option><option v-for="x in [...new Set(state.events.map(e=>e.status))]" :key="x">{{x}}</option></select></div><div class="table-card"><table><thead><tr><th>事件</th><th>类型</th><th>状态</th></tr></thead><tbody><tr v-for="e in rows" :key="e.id"><td>{{e.title}}</td><td>{{e.type}}</td><td>{{e.status}}</td></tr></tbody></table></div></section></template>
